class Solution {
public:
    int expressiveWords(string s, vector<string>& words) {
        vector<pair<char, int>> sRLE;
        int i = 0;
        int n = s.size();
        while (i < n) {
            int j = i;
            while (j < n && s[j] == s[i]) j++;
            sRLE.push_back({s[i], j - i});
            i = j;
        }

        int count = 0;
        for (const string& word : words) {
            if (isStretchy(word, sRLE)) count++;
        }
        return count;
    }

private:
    bool isStretchy(const string& word, const vector<pair<char, int>>& sRLE) {
        int i = 0;
        int n = word.size();
        int idx = 0;
        while (i < n) {
            if (idx >= (int)sRLE.size()) return false;
            int j = i;
            while (j < n && word[j] == word[i]) j++;
            int wCount = j - i;
            char c = word[i];
            if (c != sRLE[idx].first) return false;
            int sCount = sRLE[idx].second;
            if (sCount < 3) {
                if (wCount != sCount) return false;
            } else {
                if (wCount > sCount) return false;
            }
            i = j;
            idx++;
        }
        return idx == (int)sRLE.size();
    }
};
